/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_processingQueue">_processingQueue</param>
void setBlobdataProcessed(AVAMSQProcessingQueue		_processingQueue)
{

    _processingQueue.reread();
    this.conversion(_processingQueue);
    ttsbegin;
    _processingQueue.selectForUpdate(true);
    _processingQueue.update();
    ttscommit;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_processingQueue">_processingQueue</param>
protected void conversion(AVAMSQProcessingQueue       _processingQueue)
{
    str     bcommXMLStr;
    bcommXMLStr = this.convertBcomm2XML(_processingQueue);
    _processingQueue.BlobdataProcessedString = bcommXMLStr;
    _processingQueue.BlobdataProcessed = AVAMSQFileHandling::uploadStringToContainer(bcommXMLStr);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_bdeFeedbackLine">_bdeFeedbackLine</param>
/// <param name = "_transactionType">_transactionType</param>
/// <param name = "_jmgTermRegType">_jmgTermRegType</param>
/// <returns>getjobDateTime</returns>
protected str getjobDateTime(container  _bdeFeedbackLine,AVASFCTransactionType      _transactionType, JmgTermRegType _jmgTermRegType)
{
    utcDateTime         jobDateTime;
    utcdatetime         bdeSessionStartDateTime;    
    utcdatetime         bdeSessionEndDateTime;

    utcdatetime         jobStartDateTime;
    utcdatetime         jobEndDateTime;

    str                 jobDateTimeStr;

    System.Globalization.CultureInfo culture = System.Globalization.CultureInfo::get_InvariantCulture();
    bdeSessionStartDateTime = System.DateTime::ParseExact(conPeek(_bdeFeedbackLine,6) + ' ' + conpeek(_bdeFeedbackLine,7),'yyyyMMdd HHmm',culture);
    //bdeSessionEndDateTime   = System.DateTime::ParseExact(conPeek(_bdeFeedbackLine,8) + ' ' + conpeek(_bdeFeedbackLine,9),'yyyyMMdd HHmm',culture);
    bdeSessionEndDateTime   = DateTimeUtil::addMinutes(bdeSessionStartDateTime,str2Int(conpeek(_bdeFeedbackLine,10)));
    switch (_transactionType)
    {
        case AVASFCTransactionType::ClockInOut :
            jobStartDateTime = bdeSessionStartDateTime;
            jobEndDateTime = bdeSessionEndDateTime;
            break;
        case AVASFCTransactionType::JobProcessing :
            jobStartDateTime = bdeSessionStartDateTime;
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conpeek(_bdeFeedbackLine,11)));
            break;
        case AVASFCTransactionType::JobSetup :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,17)));
            break;
        case AVASFCTransactionType::Interruption01 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,18)));
            break;
        case AVASFCTransactionType::Interruption02 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,19)));
            break;
        case AVASFCTransactionType::Interruption03 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,20)));
            break;
        case AVASFCTransactionType::Interruption04 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,21)));
            break;
        case AVASFCTransactionType::Interruption05 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,22)));
            break;
        case AVASFCTransactionType::Interruption06 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,23)));
            break;
        case AVASFCTransactionType::Interruption07 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,24)));
            break;
        case AVASFCTransactionType::Interruption08 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,25)));
            break;
        case AVASFCTransactionType::Interruption09 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,26)));
            break;
        case AVASFCTransactionType::Interruption10 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,16)));
            break;
        case AVASFCTransactionType::Interruption11 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,27)));
            break;
        case AVASFCTransactionType::Interruption12 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,28)));
            break;
        case AVASFCTransactionType::Interruption13 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,29)));
            break;
        case AVASFCTransactionType::Interruption14 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,30)));
            break;
        case AVASFCTransactionType::Interruption15 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,31)));
            break;
        case AVASFCTransactionType::Interruption16 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,32)));
            break;
        case AVASFCTransactionType::Interruption17 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,33)));
            break;
        case AVASFCTransactionType::Interruption18 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,34)));
            break;
        case AVASFCTransactionType::Interruption19 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,35)));
            break;
        case AVASFCTransactionType::Interruption20 :
            jobStartDateTime = DateTimeUtil::addSeconds(prvDateTime,1);
            jobEndDateTime = DateTimeUtil::addMinutes(prvDateTime,str2Int(conPeek(_bdeFeedbackLine,36)));
            break;
            default :  break;
    }

    if(_jmgTermRegType == JmgTermRegType::ClockIn || _jmgTermRegType == JmgTermRegType::JobStart || _jmgTermRegType == JmgTermRegType::BrkFlowStart)
    {
        jobDateTime = jobStartDateTime;
    }
    if (_jmgTermRegType == JmgTermRegType::ClockOut || _jmgTermRegType == JmgTermRegType::JobStop || _jmgTermRegType == JmgTermRegType::BrkFlowStop)
    {
        jobDateTime = jobEndDateTime;
    }

    prvDateTime = jobDateTime;
    jobDateTimeStr = DateTimeUtil::toFormattedStr(jobDateTime,123,2,1,2,1,4,TimeSeparator::Colon,TimeSeparator::Colon);
    return jobDateTimeStr;
}

protected str getTimeOrigin(container   _bdeFeedbackLine, AVASFCTransactionType _transactionType)
{
    str timeOrigin;
    switch (_transactionType)
    {
        case AVASFCTransactionType::ClockInOut :
            timeOrigin = conPeek(_bdeFeedbackLine,10);
            break;
        case AVASFCTransactionType::JobProcessing :
            timeOrigin = conPeek(_bdeFeedbackLine,11);
            break;
        case AVASFCTransactionType::JobSetup :
            timeOrigin = conPeek(_bdeFeedbackLine,17);
            break;
        case AVASFCTransactionType::Interruption01 :
            timeOrigin = conPeek(_bdeFeedbackLine,18);
            break;
        case AVASFCTransactionType::Interruption02 :
            timeOrigin = conPeek(_bdeFeedbackLine,19);
            break;
        case AVASFCTransactionType::Interruption03 :
            timeOrigin = conPeek(_bdeFeedbackLine,20);
            break;
        case AVASFCTransactionType::Interruption04 :
            timeOrigin = conPeek(_bdeFeedbackLine,21);
            break;
        case AVASFCTransactionType::Interruption05 :
            timeOrigin = conPeek(_bdeFeedbackLine,22);
            break;
        case AVASFCTransactionType::Interruption06 :
            timeOrigin = conPeek(_bdeFeedbackLine,23);
            break;
        case AVASFCTransactionType::Interruption07 :
            timeOrigin = conPeek(_bdeFeedbackLine,24);
            break;
        case AVASFCTransactionType::Interruption08 :
            timeOrigin = conPeek(_bdeFeedbackLine,25);
            break;
        case AVASFCTransactionType::Interruption09 :
            timeOrigin = conPeek(_bdeFeedbackLine,26);
            break;
        case AVASFCTransactionType::Interruption10 :
            timeOrigin = conPeek(_bdeFeedbackLine,16);
            break;
        case AVASFCTransactionType::Interruption11 :
            timeOrigin = conPeek(_bdeFeedbackLine,27);
            break;
        case AVASFCTransactionType::Interruption12 :
            timeOrigin = conPeek(_bdeFeedbackLine,28);
            break;
        case AVASFCTransactionType::Interruption13 :
            timeOrigin = conPeek(_bdeFeedbackLine,29);
            break;
        case AVASFCTransactionType::Interruption14 :
            timeOrigin = conPeek(_bdeFeedbackLine,30);
            break;
        case AVASFCTransactionType::Interruption15 :
            timeOrigin = conPeek(_bdeFeedbackLine,31);
            break;
        case AVASFCTransactionType::Interruption16 :
            timeOrigin = conPeek(_bdeFeedbackLine,32);
            break;
        case AVASFCTransactionType::Interruption17 :
            timeOrigin = conPeek(_bdeFeedbackLine,33);
            break;
        case AVASFCTransactionType::Interruption18 :
            timeOrigin = conPeek(_bdeFeedbackLine,34);
            break;
        case AVASFCTransactionType::Interruption19 :
            timeOrigin = conPeek(_bdeFeedbackLine,35);
            break;
        case AVASFCTransactionType::Interruption20 :
            timeOrigin = conPeek(_bdeFeedbackLine,36);
            break;
        default :  break;
    }
    return timeOrigin;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_processingQueue">_processingQueue</param>
/// <returns>str</returns>
protected str convertBcomm2XML(AVAMSQProcessingQueue        _processingQueue)
{
    AsciiStreamIo  bcommIO = AsciiStreamIo::constructForRead(Binary::constructFromContainer(_processingQueue.Blobdata).getMemoryStream());
    container      bdeFeedbackLine;

    str            xmlMessage;

    LineNum        lineNum;
    AVANdxSFCId    ndxSFCId;
    NumberSeq      numberSeq = NumberSeq::newGetNum(NumberSeqModuleJobManager::numRefNdxSfcId());

    str addBDETransaction(AVASFCTransactionType     _sfcTransactionType,JmgTermRegType      _jmgTermReqType)
    {
        str sfcTransatcionXML;

        sfcTransatcionXML = '<AVASFCFeedbackEntity>';

        sfcTransatcionXML += strFmt('<NDXSFCId>%1</NDXSFCId>',ndxSFCId);
        sfcTransatcionXML += strFmt('<ResourceOrig>%1</ResourceOrig>',conPeek(bdeFeedbackLine,2));
        sfcTransatcionXML += strFmt('<EmplIdOrig>%1</EmplIdOrig>',conPeek(bdeFeedbackLine,3));
        sfcTransatcionXML += strFmt('<CostCentreOrig>%1</CostCentreOrig>',conPeek(bdeFeedbackLine,4));
        sfcTransatcionXML += strFmt('<JmgJobIdOrig>%1</JmgJobIdOrig>',conpeek(bdeFeedbackLine,5));
        sfcTransatcionXML += strFmt('<JmgDateTime>%1</JmgDateTime>',this.getjobDateTime(bdeFeedbackLine,_sfcTransactionType,_jmgTermReqType));
        sfcTransatcionXML += strFmt('<TimeOrig>%1</TimeOrig>',this.getTimeOrigin(bdeFeedbackLine,_sfcTransactionType));
        sfcTransatcionXML += strFmt('<TransactionType>%1</TransactionType>',enum2int(_sfcTransactionType));
        sfcTransatcionXML += strFmt('<JmgTermRegType>%1</JmgTermRegType>',enum2int(_jmgTermReqType));
        sfcTransatcionXML += strFmt('<ProdReportedGood>%1</ProdReportedGood>',conpeek(bdeFeedbackLine,12));
        sfcTransatcionXML += strFmt('<ProdReportedError>%1</ProdReportedError>',conpeek(bdeFeedbackLine,13));
        sfcTransatcionXML += strFmt('<CapacityValue>%1</CapacityValue>',conpeek(bdeFeedbackLine,15));
        sfcTransatcionXML += strFmt('<LineNum>%1</LineNum>',lineNum);

        sfcTransatcionXML +=  '</AVASFCFeedbackEntity>';

        return sfcTransatcionXML;
    }


    if (bcommIO)
    {

        bcommIO.inFieldDelimiter(';');
        bcommIO.inRecordDelimiter('\r');
        xmlMessage = '<?xml version="1.0" encoding="utf-8"?><Document>';
        while (!bcommIO.status())
        {
            lineNum = 0.00;
            bdeFeedbackLine = bcommIO.read();
            ndxSFCId        = numberSeq.num();
            xmlMessage += addBDETransaction(AVASFCTransactionType::ClockInOut,JmgTermRegType::ClockIn);
            xmlMessage += addBDETransaction(AVASFCTransactionType::JobProcessing,JmgTermRegType::JobStart);
            xmlMessage += addBDETransaction(AVASFCTransactionType::JobProcessing,JmgTermRegType::JobStop);
            if (str2Int(conPeek(bdeFeedbackLine,17)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::JobSetup,JmgTermRegType::JobStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::JobSetup,JmgTermRegType::JobStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,18)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption01,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption01,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,19)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption02,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption02,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,20)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption03,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption03,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,21)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption04,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption04,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,22)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption05,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption05,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,23)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption06,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption06,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,24)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption07,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption07,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,25)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption08,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption08,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,26)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption09,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption09,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,16)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption10,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption10,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,27)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption11,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption11,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,28)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption12,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption12,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,29)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption13,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption13,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,30)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption14,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption14,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,31)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption15,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption15,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,32)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption16,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption16,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,33)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption17,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption17,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,34)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption18,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption18,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,35)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption19,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption19,JmgTermRegType::BrkFlowStop);
            }
            if (str2Int(conPeek(bdeFeedbackLine,36)) > 0)
            {
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption20,JmgTermRegType::BrkFlowStart);
                xmlMessage += addBDETransaction(AVASFCTransactionType::Interruption20,JmgTermRegType::BrkFlowStop);
            }

            xmlMessage += addBDETransaction(AVASFCTransactionType::ClockInOut,JmgTermRegType::ClockOut);
        }
    }
    XMLMessage += '</Document>';
    return xmlMessage;
}
